from pathlib import Path
root=Path(__file__).resolve().parents[1]/'little-protagonist'
def edit(name,pairs):
 p=root/name;raw=p.read_bytes();s=raw.decode('utf8').replace('\r\n','\n')
 for a,b in pairs:
  if a in s:s=s.replace(a,b)
 p.write_bytes(s.replace('\n','\r\n').encode('utf8') if b'\r\n' in raw else s.encode('utf8'))
edit('AGENTS.md',[('前19个','前20个'),('（11—19）','（11—20）'),('第2册9个故事','第2册10个故事')])
edit('README.md',[('第4至19本通过','第4至20本通过'),('上架十九本','上架二十本'),('现有19本不代表','现有20本不代表'),('前19个故事已完成','前20个故事已完成'),('第11—19个作为第2册','第11—20个作为第2册'),('第11—19本，共68页正文、9页识字小结','第11—20本，共76页正文、10页识字小结'),('阅读PDF为80个','阅读PDF为89个'),('章节号11—19','章节号11—20'),('1、8、17、26、33、42、51、60、69。','1、8、17、26、33、42、51、60、69、78。'),('与76页连续A5书芯','与85页连续A5书芯'),('当前80页无需按4的倍数额外补齐','当前89页若按骑马订生产需另安排3个必要补齐面，阅读PDF未添加'),('第2册现更新为9故事/80页校样','第2册现更新为10故事/89页校样')])
with (root/'README.md').open('a',encoding='utf8') as f:f.write('\n### 第20本与第二册齐稿\n\n《我还不想睡》8页按正式原稿制作，使用 `book-twenty-art.js`、`book-20-assets.js`，素材与完整内置工具提示词见 `content/book-20-art-provenance.json`。7个晚间完整背景和1个同款睡鸟均已生成后复用，不再增加同构背景。主角使用原动作库，没有改真人表情或新增逐页头部尺寸。鸟在窗外树枝上、小猫在原猫垫上睡觉；原款红车在原大鞋开口中，开口轮廓遮挡车轮和车身下部。结尾主角赤脚在床边准备睡觉，对应“要睡了”，未强改照片为闭眼。\n\n第2册第11—20本十个故事齐稿，76页正文、10页识字小结、1页目录与一套封面封底，共89页A5阅读顺序PDF；连续书芯85页，外封2面A4，3毫米出血。正文起始页码1、8、17、26、33、42、51、60、69、78。第1级仍规划30篇，现有20篇不等于整级完成。89页不人为补空白，最终装订所需空白由印厂安排。原生有效ppi按实际清单，不把300dpi页面当作原图300ppi。\n')
